// Guided practice uses only temporary UI state; it never calls Game.talk/compare/assess.
const tutorialReference=reference;
const tutorialDialogue=renderDialogue;
function practiceChoices(topic){return ['listen','logic','empathy','challenge'].map((id,i)=>[id,TUTORIAL_QUESTIONS[topic][i]]);}
function lesson(){return TUTORIAL[practice.stage];}
function tutorialExplain(index=practice?.stage||0){const l=TUTORIAL[index];modal(`<h2>${l.title}</h2>${l.text.map(p=>`<p>${esc(p)}</p>`).join('')}<button id="lesson-close" class="primary">説明を閉じる</button>`);$('#lesson-close').onclick=()=>$('#modal').close();}
function tutorialLocate(){const target=lesson().target;document.querySelectorAll('.tutorial-target').forEach(e=>e.classList.remove('tutorial-target'));if(!target)return;const el=$(target);if(el){el.classList.add('tutorial-target');document.dispatchEvent(new CustomEvent('folio:reveal',{detail:{selector:target}}));}}
function advanceTutorial(){practice.stage++;if(practice.stage===11){sideTab='people';profilePerson=null;profileListPage=0;}if(practice.stage===12)sideTab='history';if(practice.stage===13)sideTab='final';if([9,10].includes(practice.stage))sideTab='notebook';view='board';board();}
beginPractice=function(){
practice={step:-1,stage:0,proof:'',snapshot:{selection:{...selection},view:state.ended?'result':(view==='reading'?'reading':state.started?'board':'cover'),shown,dialogueIndex,sideTab,profilePerson,profileListPage}};
view='board';board();
};
finishPractice=function(){const saved=practice.snapshot;practice=null;state.tutorialDone=true;save();selection=saved.selection;shown=saved.shown;sideTab=saved.sideTab;profilePerson=saved.profilePerson;profileListPage=saved.profileListPage;view=saved.view;if(view==='reading'){dialogueIndex=saved.dialogueIndex;tutorialDialogue();}else render();};
practiceGuide=function(){const l=lesson();const box=document.createElement('section');box.className='practice-guide';box.innerHTML=`<strong>操作練習 ${practice.stage+1} / ${TUTORIAL.length} · 回数は減りません — ${l.title}</strong><p>${l.task}</p><button id="tutorial-explain">詳しい説明</button>${l.target?'<button id="tutorial-locate">操作場所を表示</button>':''}<button id="practice-skip" class="quiet">練習を終える</button>`;$('#play-column').prepend(box);$('#tutorial-explain').onclick=()=>tutorialExplain();if($('#tutorial-locate'))$('#tutorial-locate').onclick=tutorialLocate;$('#practice-skip').onclick=finishPractice;requestAnimationFrame(()=>requestAnimationFrame(()=>{if(practice)tutorialLocate();}));};
reference=function(){
if(!practice)return tutorialReference();
const panel=$('#reference-panel');if(!panel)return;
if(practice.stage===9){practiceNotebook();return;}
if(practice.stage===12){panel.innerHTML='<h3>練習の会話履歴</h3><p>先ほどのやり取りを読み返してみましょう。</p><button id="practice-history" class="primary">練習の会話を読み返す</button>';$('#practice-history').onclick=()=>{modal(`<h2>練習の会話</h2>${practice.entry.lines.map(l=>`<h3>${esc(l.speaker)}</h3><p>${esc(l.text)}</p>`).join('')}<button id="practice-history-done" class="primary">読み終えたので次へ</button>`);$('#practice-history-done').onclick=()=>{$('#modal').close();advanceTutorial();};};return;}
if(practice.stage===13){panel.innerHTML='<h3>練習の説明づくり</h3><p>刻印と台帳から分かったことを文にしましょう。</p><label class="field">調べた物<select id="practice-answer-0"><option value="">選ぶ</option><option value="cup">このカップ</option><option value="hat">この帽子</option></select></label><label class="field">分かったこと<select id="practice-answer-1"><option value="">選ぶ</option><option value="manor">館の備品</option><option value="guest">客の私物</option></select></label><p id="practice-sentence">＿＿は、＿＿です。</p><button id="practice-submit" class="primary">練習の説明を確認</button><p id="practice-result" role="status"></p>';const update=()=>$('#practice-sentence').textContent=($('#practice-answer-0').value==='cup'?'このカップ':$('#practice-answer-0').value==='hat'?'この帽子':'＿＿')+'は、'+($('#practice-answer-1').value==='manor'?'館の備品':$('#practice-answer-1').value==='guest'?'客の私物':'＿＿')+'です。';$('#practice-answer-0').onchange=update;$('#practice-answer-1').onchange=update;$('#practice-submit').onclick=()=>{if($('#practice-answer-0').value==='cup'&&$('#practice-answer-1').value==='manor')advanceTutorial();else $('#practice-result').textContent='カップの刻印と館の台帳が一致しました。この2件から言える説明を選び直してみましょう。';};return;}
if(sideTab==='people')return profiles();
panel.innerHTML='<h3>右メニューの使い方</h3><p>本編では、会話を読みながら資料を確認できます。</p><p>捜査手帳：証拠・照合・キーワード・噂・推理メモ。</p><p>人物資料：16人のアイコンから詳しい情報を表示。</p><p>会話履歴：過去の対話を読み返す。</p><p>最終推理：集めた言葉で事件を説明する。</p><p>練習中は本編の証拠や履歴を変更しません。</p>';
};
practiceBoard=function(){
// Build the normal shell, then show only the control being learned.
tab='investigate';baseBoard();$('#app .tabs')?.remove();const panel=$('#panel'),l=lesson();panel.innerHTML=`<h3>${l.title}</h3>${l.text.map(p=>`<p>${esc(p)}</p>`).join('')}<div id="tutorial-action"></div>`;const action=$('#tutorial-action');
if(l.next){action.innerHTML=`<button id="tutorial-next" class="primary">${l.next}</button>`;$('#tutorial-next').onclick=()=>practice.stage===14?finishPractice():advanceTutorial();}
if([2,3].includes(practice.stage)){const which=practice.stage===2?'a':'b';action.innerHTML=personPickerButton(HISUI.people[selection[which]],which);action.querySelector('button').onclick=()=>{openPersonPicker(which);document.querySelectorAll(`[data-${which}]`).forEach(el=>el.onclick=()=>{selection[which]=Number(el.dataset[which]);if(selection.a===selection.b)selection.b=(selection.a+1)%16;$('#modal').close();advanceTutorial();});};}
if(practice.stage===4){action.innerHTML=`<div class="topic-options">${HISUI.topics.map(t=>`<button data-topic="${t[0]}">${t[1]}</button>`).join('')}</div>`;action.querySelectorAll('button').forEach(b=>b.onclick=()=>{selection.topic=b.dataset.topic;advanceTutorial();});}
if(practice.stage===5){action.innerHTML=`<div class="options">${practiceChoices(selection.topic).map(([id,text])=>`<button data-approach="${id}">${esc(text)}</button>`).join('')}</div>`;action.querySelectorAll('button').forEach(b=>b.onclick=()=>{selection.approach=b.dataset.approach;advanceTutorial();});}
if(practice.stage===6){action.innerHTML='<label class="field">提示する練習用の証拠<select id="practice-proof-select"><option value="">証拠を提示しない</option><option value="cup">カップの観察（練習用）</option></select></label><button id="practice-proof-confirm" class="primary">この内容で確認する</button>';$('#practice-proof-select').value=practice.proof;$('#practice-proof-confirm').onclick=()=>{practice.proof=$('#practice-proof-select').value;advanceTutorial();};}
if(practice.stage===7){action.innerHTML=`<p>${HISUI.people[selection.a].name} → ${HISUI.people[selection.b].name}</p><p>話題：${HISUI.topics.find(t=>t[0]===selection.topic)[1]}</p><p>選んだセリフ：${esc(practiceChoices(selection.topic).find(v=>v[0]===selection.approach)[1])}</p><p>証拠：${practice.proof?'カップの観察':'提示しない'}</p><button id="talk" class="primary">練習の対話</button>`;$('#talk').onclick=()=>{practice.stage=8;practice.entry={turn:0,a:selection.a,b:selection.b,topic:selection.topic,outcome:'操作練習',gained:[],keys:[],lines:[{speaker:HISUI.people[selection.a].name,text:practiceChoices(selection.topic).find(v=>v[0]===selection.approach)[1]},...(practice.proof?[{speaker:HISUI.people[selection.a].name,text:'このカップを一緒に見てほしい。底に「翡翠荘」と書かれているね。'}]:[]),{speaker:HISUI.people[selection.b].name,text:selection.approach==='challenge'?'いきなり疑われると、話しづらいな。まずは何が分かっているか、一緒に見てみよう。':'一緒に確かめよう。カップの底の刻印なら、館の備品台帳と比べられそうだね。'},{speaker:'地の文',text:'練習用のカップと備品台帳が揃った。次は、手帳で共通点を探してみよう。'}]};shown=practice.entry;view='reading';render();};}
workspace();
if([9,11,12,13].includes(practice.stage))document.querySelectorAll('[data-reference]').forEach(b=>{b.disabled=b.dataset.reference!==sideTab;});
if(practice.stage===11){document.querySelectorAll('[data-reference="people"]').forEach(b=>b.onclick=()=>{sideTab='people';profilePerson=null;profiles();});}
};
renderDialogue=function(){if(!practice)return tutorialDialogue();baseDialogue();workspace();if($('#dialogue-done')){$('#dialogue-done').textContent='練習の記録を見る';$('#dialogue-done').onclick=advanceTutorial;}const target=$('#line-next')||$('#dialogue-done');target?.classList.add('tutorial-target');};
practiceNotebook=function(){const panel=$('#reference-panel');panel.innerHTML='<h3>練習用の記録</h3><article class="list-entry"><h3>カップの観察</h3><p>底面に「翡翠荘」の刻印がある。</p></article><article class="list-entry"><h3>備品台帳</h3><p>館のカップには「翡翠荘」の刻印がある。</p></article>'+[0,1].map(i=>`<label class="field">記録 ${i+1}<select id="practice-proof-${i}"><option value="">選んでください</option><option value="cup">カップの観察</option><option value="inventory">備品台帳</option></select></label>`).join('')+'<button id="practice-compare" class="primary">練習の照合</button><p id="practice-feedback" role="status"></p>';$('#practice-compare').onclick=()=>{if($('#practice-proof-0').value&&$('#practice-proof-1').value&&$('#practice-proof-0').value!==$('#practice-proof-1').value)advanceTutorial();else $('#practice-feedback').textContent='同じ記録どうしでは比べられません。「カップの観察」と「備品台帳」を一つずつ選びましょう。回数も信頼も減っていません。';};};
const tutorialProfiles=profiles;
profiles=function(){tutorialProfiles();if(practice?.stage===11){document.querySelectorAll('[data-profile]').forEach(b=>{const original=b.onclick;b.onclick=()=>{original();const panel=$('#reference-panel');panel.insertAdjacentHTML('beforeend','<button id="practice-profile-done" class="primary">人物資料を確認したので次へ</button>');$('#practice-profile-done').onclick=advanceTutorial;panel.querySelector('[data-viewpoint]')?.remove();};});}};
function showHelp(){modal(`<h2>遊び方・操作ガイド</h2><p>知りたい項目を選んでください。説明を読むだけでは対話の回数を使いません。</p><button id="replay-tutorial" class="primary">操作練習をやり直す</button><div class="help-topics">${TUTORIAL.map((l,i)=>`<button data-help-topic="${i}">${i+1}. ${l.title}</button>`).join('')}</div>`);$('#replay-tutorial').onclick=()=>{$('#modal').close();if(practice){practice.stage=0;view='board';board();}else beginPractice();};document.querySelectorAll('[data-help-topic]').forEach(b=>b.onclick=()=>{const l=TUTORIAL[Number(b.dataset.helpTopic)];$('#modal-body').innerHTML=`<h2>${l.title}</h2>${l.text.map(p=>`<p>${esc(p)}</p>`).join('')}<button id="help-index">項目一覧へ戻る</button>`;$('#modal-body').dataset.folioStart='0';$('#help-index').onclick=showHelp;});}
$('#help').onclick=showHelp;
